def varint(d,o):
    v=0
    for i in range(9):
        b=d[o+i]
        if i==8:
            v=(v<<8)|b; return v,o+9
        v=(v<<7)|(b&0x7f)
        if not b&0x80: return v,o+1
    raise ValueError

def serial_size(t):
    if t==0: return 0,None
    if t in (1,2,3,4,5,6): return (1,2,3,4,6,8)[t-1],'int'
    if t==7: return 8,'float'
    if t==8: return 0,('int',0)
    if t==9: return 0,('int',1)
    if t in (10,11): return 0,None
    if t%2==0: return (t-12)//2,'blob'
    return (t-13)//2,'text'

def decode(rec):
    hlen,o=varint(rec,0)
    types=[]; p=o
    while p<hlen:
        t,p=varint(rec,p); types.append(t)
    vals=[]; p=hlen
    for t in types:
        sz,kind=serial_size(t)
        raw=rec[p:p+sz]; p+=sz
        if kind=='int': vals.append(int.from_bytes(raw,'big',signed=True) if sz else kind[1] if isinstance(kind,tuple) else None)
        elif kind=='float': vals.append(struct.unpack('>d',raw)[0])
        elif kind=='text': vals.append(raw.decode('utf-8','replace'))
        elif kind=='blob': vals.append(raw.hex())
        else: vals.append(None)
    return vals

